#include "CadDocument.h"
#include "SketchGeometry.h"
#include <QCoreApplication>
#include <QTemporaryDir>
#include <iostream>
#include <cmath>
#include <BRep_Tool.hxx>
#include <TopExp.hxx>
#include <TopTools_IndexedMapOfShape.hxx>
#include <TopoDS.hxx>
void check(bool b,const char* m){if(!b)throw std::runtime_error(m);}
QJsonObject ref(const EvaluatedSupportFace& f){return {{"producerFeatureId",f.producerFeatureId},{"bodyId",f.bodyId},{"faceId",f.faceId}};}
int main(int argc,char** argv){QCoreApplication app(argc,argv);try{
 CadDocument d;auto a=d.authored();const auto id=CadDocument::newId(),body=CadDocument::newId(),plane=CadDocument::newId();a["features"]=QJsonArray{QJsonObject{{"id",id},{"bodyId",body},{"type","box"},{"name","Box"},{"visible",true},{"parameters",QJsonObject{{"widthMm",40},{"depthMm",20},{"heightMm",20},{"xMm",0},{"yMm",0},{"zMm",0}}}},QJsonObject{{"id",plane},{"type","constructionPlane"},{"name","Neutral"},{"visible",true},{"parameters",QJsonObject{{"source",QJsonObject{{"plane","XY"}}},{"offsetMm",0}}}}};
 auto initialFeatures=a.value("features").toArray();for(int i=0;i<initialFeatures.size();++i){auto row=initialFeatures[i].toObject();row["ownerId"]=a.value("documentId");initialFeatures[i]=row;}a["features"]=initialFeatures;
 auto commit=[&](const QJsonObject& c){const auto e=d.commit(c,"Draft fixture");if(!e.isEmpty())throw std::runtime_error(e.toStdString());};commit(a);const auto source=d.authored();
 EvaluatedSupportFace f;for(const auto& face:d.bodies()[0].supportFaces)if(face.frame.value("normal").toArray()[1].toDouble()<-.99)f=face;check(!f.faceId.isEmpty(),"front face");
 QJsonObject args{{"targetBodyId",body},{"face",ref(f)},{"neutralPlaneId",plane},{"flipPullDirection",false},{"angleDeg",5}};
 for(double angle:{5.,-5.})for(bool flip:{false,true}){args["angleDeg"]=angle;args["flipPullDirection"]=flip;auto c=CadDocument::draftCandidate(source,args);auto e=CadDocument::evaluateCandidate(c);if(!e.ok)throw std::runtime_error(e.error.toStdString());const auto b=e.evaluation->bodies[0];const double expected=16000-(flip?-1:1)*8000*std::tan(angle*std::acos(-1.)/180.);check(std::abs(b.summary.value("volumeMm3").toDouble()-expected)<1e-5,"signed analytic volume");check(b.supportFaces.size()==6,"all exact face descendants");for(const auto& old:d.bodies()[0].supportFaces)if(old.faceId!=f.faceId){const auto next=std::find_if(b.supportFaces.begin(),b.supportFaces.end(),[&](const auto& x){return x.faceId==old.faceId && x.producerFeatureId==old.producerFeatureId;});check(next!=b.supportFaces.end() && next->frame==old.frame,"unchanged face identity and frame");}for(const auto& side:b.supportFaces)if(side.role=="draft.side"){TopTools_IndexedMapOfShape corners;TopExp::MapShapes(side.face,TopAbs_VERTEX,corners);check(corners.Extent()==4,"four drafted side corners");for(int i=1;i<=corners.Extent();++i){const auto v=BRep_Tool::Pnt(TopoDS::Vertex(corners(i)));check(std::abs(v.Y()-v.Z()*std::tan(angle*std::acos(-1.)/180.)*(flip?-1:1))<1e-6,"signed top shift and fixed hinge");}}check(d.authored()==source,"disposable preview");check(std::abs(GeometryKernel::summarize(d.bodies()[0].shape).value("volumeMm3").toDouble()-16000)<1e-6,"source B-rep remains unchanged");}
 args["angleDeg"]=5;args["flipPullDirection"]=false;commit(CadDocument::draftCandidate(source,args));const auto drafted=d.authored();const auto draftId=drafted.value("features").toArray().last().toObject().value("id");EvaluatedSupportFace side;for(const auto& x:d.bodies()[0].supportFaces)if(x.role=="draft.side")side=x;check(!side.faceId.isEmpty(),"draft support");
 // The retained tilted frame is authoritative for a downstream sketch/cut.
 auto wall=SketchGeometry::newSupportedFeature(d.authored().value("documentId").toString(),ref(side),"Draft wall");double u=0,v=0;const QJsonArray center{20,10*std::tan(5*std::acos(-1.)/180.),10};for(int axis=0;axis<3;++axis){const double delta=center[axis].toDouble()-side.frame.value("origin").toArray()[axis].toDouble();u+=delta*side.frame.value("uAxis").toArray()[axis].toDouble();v+=delta*side.frame.value("vAxis").toArray()[axis].toDouble();}wall=SketchGeometry::addCircle(wall,{{"centerUMm",u},{"centerVMm",v},{"diameterMm",4}});auto sketch=d.authored();auto fs=sketch.value("features").toArray();fs.append(wall);sketch["features"]=fs;commit(sketch);const auto profile=d.evaluation().sketches.back().profiles[0].profileId;commit(CadDocument::extrusionCandidate(d.authored(),{{"sketchId",wall.value("id")},{"profileId",profile},{"distanceMm",-2},{"operation","cut"},{"targetBodyIds",QJsonArray{body}}}));
 args["featureId"]=draftId;args["angleDeg"]=3;commit(CadDocument::draftCandidate(d.authored(),args));const auto good=d.authored();check(std::abs(d.bodies()[0].summary.value("volumeMm3").toDouble()-(16000-8000*std::tan(3*std::acos(-1.)/180.)-8*std::acos(-1.)))<1e-5,"downstream Cut volume after edit");EvaluatedSupportFace editedSide;for(const auto& x:d.bodies()[0].supportFaces)if(x.role=="draft.side")editedSide=x;check(!editedSide.faceId.isEmpty(),"downstream exact face");check(d.evaluation().sketches.back().resolvedFrame==editedSide.frame,"downstream rotated frame");
 args["angleDeg"]=80;check(!d.commit(CadDocument::draftCandidate(good,args),"refused").isEmpty() && d.authored()==good,"atomic crossed-wall refusal");d.history().undo();d.history().redo();check(d.authored()==good,"undo redo");QTemporaryDir temp;auto path=temp.filePath("draft.alloy");check(d.save(path).isEmpty(),"save");CadDocument reopened;check(reopened.open(path).isEmpty() && reopened.authored()==good,"reopen");auto upstream=good;auto rows=upstream.value("features").toArray();auto box=rows[0].toObject(),bp=box.value("parameters").toObject();bp["heightMm"]=24;box["parameters"]=bp;rows[0]=box;upstream["features"]=rows;commit(upstream);check(std::abs(d.bodies()[0].summary.value("volumeMm3").toDouble()-(19200-11520*std::tan(3*std::acos(-1.)/180.)-8*std::acos(-1.)))<1e-5,"upstream prism dimensions recompute Draft and supported Cut");
 std::cout<<"Draft signed geometry, pull flip, exact face frames, preview/edit/history/reopen/refusal passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
